import{_ as a,o as i,c as l,a6 as d}from"./chunks/framework.B_q3ZJNF.js";const c=JSON.parse('{"title":"A股的游戏规则：竞价、T+1、涨跌停与成本","description":"","frontmatter":{"title":"A股的游戏规则：竞价、T+1、涨跌停与成本"},"headers":[],"relativePath":"astock-course/03-market-rules.md","filePath":"astock-course/docs/03-market-rules.md"}'),e={name:"astock-course/03-market-rules.md"};function s(r,t,h,p,o,n){return i(),l("div",null,[...t[0]||(t[0]=[d(`<h1 id="a股的游戏规则-竞价、t-1、涨跌停与成本" tabindex="-1">A股的游戏规则：竞价、T+1、涨跌停与成本 <a class="header-anchor" href="#a股的游戏规则-竞价、t-1、涨跌停与成本" aria-label="Permalink to &quot;A股的游戏规则：竞价、T+1、涨跌停与成本&quot;">​</a></h1><p>钱的时间尺子和公司的两因子账本已经在你手里（第 1、2 章）。真金白银进场之前还剩最后一层：交易所的游戏规则。这一章一次给你六块新积木，全部指向三个下单前必须能回答的问题——单子什么时候成交；买到的股票什么时候能卖；一买一卖要扣走多少。三个问题都有唯一正确的算法，本章结束前，你要能对任意一笔委托各给出一个数。</p><h2 id="工具箱" tabindex="-1">工具箱 <a class="header-anchor" href="#工具箱" aria-label="Permalink to &quot;工具箱&quot;">​</a></h2><p>本章顺手调用七块旧积木。货币时间价值——跨期比较前先把钱折到同一时点（第 1 章）；收益率——（期末 − 期初）÷ 期初（第 1 章）；复利——终值 = 本金 ×（1 + 收益率）^年数（第 1 章）；实际购买力——实际收益率 ≈ 名义收益率 − 通胀率（第 1 章）；市值——股价 × 总股本，公司的总标价（第 2 章）；盈利——公司一段时期赚到的净利润（第 2 章）；估值——价格相对基本面的倍数关系（第 2 章）。够用了，规则章不需要更多。</p><h2 id="词表-六个新名词先领进门" tabindex="-1">词表：六个新名词先领进门 <a class="header-anchor" href="#词表-六个新名词先领进门" aria-label="Permalink to &quot;词表：六个新名词先领进门&quot;">​</a></h2><p>先挂一张词表当名片，每个名字本章都会当场展开；读后文时随时翻回来对号。</p><table tabindex="0"><thead><tr><th>术语</th><th>它是什么</th><th>拿来做什么</th></tr></thead><tbody><tr><td>集合竞价</td><td>把一段时间内收到的买卖申报集中进同一个池子，按能让总成交量最大的价格一次性撮合出唯一成交价——开盘价与收盘价都由它产生</td><td>看懂价格从哪来</td></tr><tr><td>T+1</td><td>当日买入的股票，次一交易日才能卖出（现行载体为沪深交易所《交易规则》）——当日卖出所得资金当日可用、次日可取</td><td>判定一笔买入最早何时能卖</td></tr><tr><td>涨跌停板</td><td>以前收盘价为基准，限制当日报价的最大波动幅度——情绪再大也要分几天消化</td><td>算出当天价格的上下界</td></tr><tr><td>印花税</td><td>卖出股票时按成交金额向卖方单边征收的税，现行万分之 5（0.05%）</td><td>只在卖出时算一次</td></tr><tr><td>佣金</td><td>券商按成交金额双向收取的经纪服务费——本章按万分之 2.5、单笔最低 5 元演算</td><td>每一笔买卖都要算</td></tr><tr><td>过户费</td><td>中国结算按成交金额双向收取的股权登记过户费——现行万分之 0.1（0.001%）</td><td>每一笔都要算，金额很小</td></tr></tbody></table><h2 id="两张下单截图-一个不成交-一个卖不掉" tabindex="-1">两张下单截图：一个不成交，一个卖不掉 <a class="header-anchor" href="#两张下单截图-一个不成交-一个卖不掉" aria-label="Permalink to &quot;两张下单截图：一个不成交，一个卖不掉&quot;">​</a></h2><p>第一幕，9:20，开盘前。你挂出一笔买单：比昨天的收盘价低 3%，想捡个便宜。软件显示「已报」，然后是漫长的安静——9:22 没有成交回报，9:24 还是没有。9:25 一过，结果才跳出来：成交，或者没成交，二选一。</p><p>第二幕，14:00，同一个交易日。你上午买的另一只股票涨了 4%，想落袋为安，点卖出——弹回来一行字：废单。废单指的是被交易所拒绝的委托：不成交、不进入价格、只留下一条失败记录。上午明明买到了，下午居然卖不掉。</p><p>这两幕你随时可以在行情软件里复现：交易日的 9:15 到 9:25 挂一单试试（9:20 之后撤不掉，练习请用模拟盘）；至于废单，等你哪天上午买入、下午忍不住想卖，市场会亲自演示。两个瞬间都不是软件坏了。第一个是集合竞价在收单：9:15 到 9:25 的申报先进池子、后撮合，9:25 才揭晓。第二个是 T+1 在站岗：今天买入的股票，今天就是不能卖。这两条规则加上涨跌停板和三项费用，就是本章的全部内容——它们不玄，每一条都能算。</p><h2 id="竞价与-t-1-价格从哪来-股票何时能卖" tabindex="-1">竞价与 T+1：价格从哪来，股票何时能卖 <a class="header-anchor" href="#竞价与-t-1-价格从哪来-股票何时能卖" aria-label="Permalink to &quot;竞价与 T+1：价格从哪来，股票何时能卖&quot;">​</a></h2><h3 id="一个交易日的时刻表" tabindex="-1">一个交易日的时刻表 <a class="header-anchor" href="#一个交易日的时刻表" aria-label="Permalink to &quot;一个交易日的时刻表&quot;">​</a></h3><ul><li>9:15–9:25，开盘集合竞价：申报进池子；其中 9:20–9:25 不可撤单；</li><li>9:25，开盘价揭晓，池子里的申报按同一个价格撮合；</li><li>9:30–11:30、13:00–14:57，连续竞价：申报随到随撮合——卖价不高于买价就成交，价格优先（报价更慷慨的一方先成交）、时间优先（同价按下单先后排）；</li><li>14:57–15:00，收盘集合竞价：再用一次池子，定出收盘价；</li><li>15:00 收盘，也是交易日分界线：15:00 之前下的单算这个交易日，之后的算下一个交易日。</li></ul><h3 id="开盘价是算出来的" tabindex="-1">开盘价是算出来的 <a class="header-anchor" href="#开盘价是算出来的" aria-label="Permalink to &quot;开盘价是算出来的&quot;">​</a></h3><p>先替直觉说句公道话：很多人以为开盘价是某个大机构定的，或者干脆是随机跳出来的。反过来想：要是 9:30 一开盘就让订单逐笔对撞，谁的单先到谁先得，开盘价就由手速和运气决定。集合竞价不这么干，它把头 10 分钟的申报攒进一个池子，按最大成交量原则——能让成交股数最大的那个价格——一次定出唯一成交价。</p><p>看一个五张申报的教学示意（数字为虚构，机制真实）：</p><ul><li>卖方：9.98 元 × 2000 股、10.00 元 × 3000 股、10.02 元 × 1000 股；</li><li>买方：10.02 元 × 2500 股、10.00 元 × 3000 股。</li></ul><p>把每个候选价都试一遍：买价不低于候选价的申报，和卖价不高于候选价的申报，能凑成多少股？</p><table tabindex="0"><thead><tr><th>候选价</th><th>买方能接受的股数</th><th>卖方能接受的股数</th><th>能成交</th></tr></thead><tbody><tr><td>9.98</td><td>5500</td><td>2000</td><td>2000</td></tr><tr><td>10.00</td><td>5500</td><td>5000</td><td>5000</td></tr><tr><td>10.01</td><td>2500</td><td>5000</td><td>2500</td></tr><tr><td>10.02</td><td>2500</td><td>6000</td><td>2500</td></tr></tbody></table><p>10.00 一行胜出，而且是唯一最大——开盘价 10.00 元，成交 5000 股。注意两个细节：9.98 元的卖单按 10.00 成交，不是按它自己写的 9.98，池子里所有人共用同一个成交价；10.00 的买单 3000 股只成交了其中 2500 股，剩下的按时间优先排队，带进 9:30 开始的连续竞价。9:20 那张单子要等到 9:25 才知道生死，不是系统慢，是比赛还没结束。<strong>开盘价不是谁喊出来的，是全场算出来的。</strong></p><h3 id="t-1-周五买入-最快下周一卖" tabindex="-1">T+1：周五买入，最快下周一卖 <a class="header-anchor" href="#t-1-周五买入-最快下周一卖" aria-label="Permalink to &quot;T+1：周五买入，最快下周一卖&quot;">​</a></h3><p>T+1 这条规矩，1998 年版《证券法》第 106 条曾白纸黑字写着「当日买入的证券，不得在当日再行卖出」；2005 年法律修订删去这一条后，它由沪深交易所的《交易规则》继续承载。交易所规则没给这条规矩附说明书，这里不编成因；它对账户的效果一清二楚——上午买入、下午卖出，委托直接弹回，钩子里那张废单就是这么来的。附带两条资金规则：当日卖出收回的资金，当日可以继续买股票，下一交易日才能转进银行卡；「日」一律指交易日，不是自然日——周五买入，要数到下一个交易日，也就是下周一。</p><p>把 15:00 分界、交易日历和 T+1 接起来，得到本章第一台小机器，三步判定任何一笔委托：</p><ol><li>定归属：下单时刻在 15:00 之前，T 就是当天；之后，T 滚入下一个交易日；</li><li>数格子：T+1 按交易日数，周五之后跳过周末（节假日以交易所公告为准，本章演算只走周一到周五）；</li><li>得答案：最早可卖日就是 T 的下一个交易日。</li></ol><p>演算台里就是这么判定的：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 用法示例 · companion/src/costs.ts · earliestSellDay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">earliestSellDay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;周五&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;10:00&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → &#39;周一&#39;：T 是周五，跳过周末</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">earliestSellDay</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;周五&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;15:01&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// → &#39;周二&#39;：单子滚入下周一，再数一格</span></span></code></pre></div><h2 id="涨跌停板-一天之内价格的刻度" tabindex="-1">涨跌停板：一天之内价格的刻度 <a class="header-anchor" href="#涨跌停板-一天之内价格的刻度" aria-label="Permalink to &quot;涨跌停板：一天之内价格的刻度&quot;">​</a></h2><p>反事实先来：要是没有这条边界，一只被疯狂追捧的股票可以在一天之内从 10 元喊到 30 元，再在恐慌里砸回 5 元，报价跟着情绪狂奔。涨跌停板把单日波动钉在前收盘价的一个百分比之内，情绪再大也要分几天消化。它管的是报价的刻度，不是公司那本账——盈利与估值因子（第 2 章）不会因为一条涨停线改变，改变的只是它们今天允许显示的幅度；股本不变时，涨跌幅也就是市值单日变动的上下限：市值 200 亿的主板公司，涨停日市值最多 220 亿。</p><p>现行幅度如下（生效日期见括注；你读到时若已修订，以交易所最新公告为准）：</p><table tabindex="0"><thead><tr><th>板块</th><th>单日涨跌幅</th></tr></thead><tbody><tr><td>主板（含 ST、*ST）</td><td>±10%（2026-07-06 沪深北交易所修订交易规则施行起统一；此前主板 ST 按 5% 的旧口径已失效，老教程别再照抄）</td></tr><tr><td>创业板、科创板</td><td>±20%</td></tr><tr><td>北交所</td><td>±30%</td></tr></tbody></table><p>主板、创业板与科创板的新股上市后前 5 个交易日不设涨跌幅——头几天没有刻度，价格自己找位置。涨跌停价的算法一行：</p><blockquote><p><strong>涨跌停价 = 前收盘 ×（1 ± 幅度）</strong>，四舍五入到 0.01 元（A 股最小报价单位）。</p></blockquote><p>跟算一道整的：主板某股前收盘 10.00 元，涨停价 10.00 × 1.1 = 11.00 元，跌停价 9.00 元。带零头的先钉在这：前收盘 12.37 元的话，12.37 × 1.1 = 13.607，四舍五入到分是 13.61；12.37 × 0.9 = 11.133，落到 11.13——这道题留到验证环节由你亲手算。顺带钉一个易错点：跌停不是判决书，触及跌停只说明在这个价位上卖方压倒了买方，它不预言明天；把跌停当成自动卖出的理由，是把单日现象当成了终审。至于放量还是缩量、开在什么位置——那要等成交量这块积木登场才有资格判断，本章只证伪「跌停=反转」这一半。</p><h2 id="成本-一买一卖-五笔账" tabindex="-1">成本：一买一卖，五笔账 <a class="header-anchor" href="#成本-一买一卖-五笔账" aria-label="Permalink to &quot;成本：一买一卖，五笔账&quot;">​</a></h2><p>行情软件里那个「成交价」不是这笔交易的全部价格。一买一卖之间埋着五笔账：两笔佣金、两笔过户费、一笔印花税。漏掉其中几笔，收益计算就会系统性偏乐观。三项费用各有各的收法（费率与生效日期为公告口径，2026 年 9 月核对；若已调整，以最新公告为准）：</p><ol><li>佣金——券商收的通道与服务费，买卖双向，每笔按成交金额乘费率。本章全程用万分之 2.5（0.025%）、单笔不足 5 元按 5 元收作课程示例值；你的实际费率以开户合同为准，开户前可以谈。</li><li>印花税——国家收的税，只在卖出时向卖方征收：卖出金额 × 万分之 5（0.05%），依据财政部 税务总局公告 2023 年第 39 号，2023-08-28 起施行。买入侧没有这一项。</li><li>过户费——中国结算收的股权登记费，买卖双向：成交金额 × 万分之 0.1（0.001%），2022-04-29 起施行。小到常被忽略，但每笔都在。</li></ol><p>五笔账合总就是本章的组装式：</p><blockquote><p><strong>完整成本 = 买入佣金 + 买入过户费 + 卖出佣金 + 卖出过户费 + 卖出印花税</strong></p></blockquote><p>「佣金是股票交易唯一的成本」这个流传最广的说法在这里破产：佣金通常是大头，但印花税在卖出侧单笔就可能追平甚至超过两笔佣金之和（成本题 B 就是）。把印花税记到买入头上的「买卖都交税」同样错——买入侧只有佣金和过户费两笔。再用货币时间价值的眼睛看一眼（第 1 章）：这五笔账是今天就确定的现金流出，没有等待、没有悬念；它们一旦扣掉，就永远退出了复利的队伍——本章演练里那 13.11 元的成本，按 6% 复利放 20 年是 42.05 元。省下的每一分费用都是当场到手的实际购买力（第 1 章），不需要任何行情兑现。<strong>费用是进场前就能算死的数，收益是进场后才知道的数。</strong></p><p>还有一条硬规则要先铺好：主板与创业板的股票按「手」交易，1 手 = 100 股，买入至少 1 手；科创板单笔申报不低于 200 股，超出部分按 1 股递增（上交所投资者教育口径）。本章成本题里的「1 手」就是 100 股。</p><h2 id="演练-跟着算一笔完整的" tabindex="-1">演练：跟着算一笔完整的 <a class="header-anchor" href="#演练-跟着算一笔完整的" aria-label="Permalink to &quot;演练：跟着算一笔完整的&quot;">​</a></h2><p>本章所有承重数字出自演算台的 <code>fixtures/market-rules.json</code>，由 <code>tests/costs.test.ts</code> 逐分锁定；费率为课程示例值。准备纸笔，先跟算成本题 A：10.00 元买入 500 股（5 手），12.00 元全部卖出。</p><p>买入这一侧：</p><ol><li>成交金额：10.00 × 500 = 5000.00 元；</li><li>买入佣金：5000 × 万分之 2.5 = 1.25 元，不足 5 元，按 5.00 元收；</li><li>买入过户费：5000 × 万分之 0.1 = 0.05 元；</li><li>买入总付出：5000 + 5.00 + 0.05 = 5005.05 元。</li></ol><p>卖出这一侧：</p><ol start="5"><li>成交金额：12.00 × 500 = 6000.00 元；</li><li>卖出佣金：6000 × 万分之 2.5 = 1.50 元，仍不足 5 元，按 5.00 元收；</li><li>卖出过户费：0.06 元；</li><li>印花税：6000 × 万分之 5 = 3.00 元；</li><li>卖出总到手：6000 − 5.00 − 0.06 − 3.00 = 5991.94 元。</li></ol><p>合账：</p><ol start="10"><li>价差：6000 − 5000 = 1000.00 元；</li><li>完整成本：5.00 + 0.05 + 5.00 + 0.06 + 3.00 = 13.11 元；</li><li>净落袋：5991.94 − 5005.05 = 986.89 元。</li></ol><p>读一遍结果：价差 1000 元，到手 986.89 元，13.11 元留在通道里，其中 10 元是两笔「保底」佣金——按真实费率本该只收 2.75 元。净收益率 = 986.89 ÷ 5005.05 ≈ 19.72%（收益率积木的老用法，第 1 章），比账面的 20% 矮了 0.28 个百分点，这就是成本在收益率上留下的齿印。记住这套动作：买入侧两笔费、卖出侧三笔费，合总五笔。</p><h2 id="验证-七道题-猜完再动手" tabindex="-1">验证：七道题，猜完再动手 <a class="header-anchor" href="#验证-七道题-猜完再动手" aria-label="Permalink to &quot;验证：七道题，猜完再动手&quot;">​</a></h2><p>下面七道题先落纸写离散的猜测——写区间、写二选一，不写「应该不少」——再动手算，最后展开核对。答案与演算台 fixtures 应当逐分一致。</p><p>第一题（成本题 B）：20.00 元买入 2000 股，22.00 元全部卖出。先猜：完整成本落在 25 元以下、25 到 45 元，还是 45 元以上？净落袋能超过 3950 元吗？</p><details><summary>成本题 B 答案</summary><p>买入 40000.00 元：佣金 10.00 元（这次过了下限，按真实费率收）、过户费 0.40 元，总付出 40010.40 元。卖出 44000.00 元：佣金 11.00 元、过户费 0.44 元、印花税 22.00 元，到手 43966.56 元。完整成本 43.84 元，落在 25 到 45 一桶；净落袋 3956.16 元，超过 3950。成本只占价差的约 1.1%——单子一大，费率的实际咬人程度就轻了。顺带看一眼：这题的印花税 22.00 元，比两笔佣金之和 21.00 元还多，「佣金是唯一成本」在这张单上已经不成立。</p></details><p>第二题（成本题 C）：8.00 元买入 1 手，8.80 元全部卖出。先猜：净落袋在 78 元以上、70 到 78 元，还是 70 元以下？</p><details><summary>成本题 C 答案</summary><p>买入 800.00 元：佣金按下限 5.00 元、过户费 0.01 元，总付出 805.01 元。卖出 880.00 元：佣金 5.00 元、过户费 0.01 元、印花税 0.44 元，到手 874.55 元。净落袋 69.54 元，落在 70 以下。完整成本 10.46 元，吃掉价差 80 元的约 13%；其中两笔佣金 10.00 元全部来自 5 元下限——按万分之 2.5 本该只收 0.42 元。同一套费率，这题的成本占比约是成本题 B（1.1%）的 12 倍：小额单最怕的不是费率，是下限。</p></details><p>第三题（涨跌停题）：主板某股前收盘 12.37 元。先二选一：涨停价是 13.61 还是 13.60？跌停价是 11.13 还是 11.14？</p><details><summary>涨跌停题答案</summary><p>12.37 × 1.1 = 13.607，四舍五入到分，涨停价 13.61；12.37 × 0.9 = 11.133，落到 11.13。涨跌停价必须落在最小报价单位上，零头一律处理到分——你若猜了 13.60 或 11.14，差的就是这一步取整。</p></details><p>第四到第七题（时点题）：每行先填两个格子——归属交易日 T 和最早可卖日，再展开核对。</p><table tabindex="0"><thead><tr><th>题</th><th>委托</th><th>T 是？</th><th>最早可卖是？</th></tr></thead><tbody><tr><td>四</td><td>周三 14:30 买入成交</td><td>？</td><td>？</td></tr><tr><td>五</td><td>周五 15:01 下单买入</td><td>？</td><td>？</td></tr><tr><td>六</td><td>周五 10:00 买入成交</td><td>？</td><td>？</td></tr><tr><td>七</td><td>周四 15:10 下单买入</td><td>？</td><td>？</td></tr></tbody></table><details><summary>时点题答案</summary><p>四：T 是周三，最早周四。五：15:00 之后下单，滚入下一交易日，T 是下周一，最早下周二。六：T 是周五，T+1 跳过周末，最早下周一。七：滚入周五，T 是周五，最早下周一。第五题只比「当天」晚了一分钟，答案却差出一整个周末——15:00 这条分界线的作用就是这么硬。</p></details><p>定向破坏：把「印花税只在卖出侧征收」这条规则拆掉，假设买入也要交万分之 5，重算成本题 B 的完整成本。先落纸一个可判定的预言——成本恰好多出多少元：20.00、22.00，还是 2.00？然后动手：买入侧多出 40000 × 万分之 5 = 20.00 元，完整成本 43.84 变成 63.84，净落袋 3956.16 变成 3936.16。再看哪条没动：卖出侧三笔费用一分没变——被拆掉的那条口径守护的正是「税向卖方单边征收」（2023-08-28 起现行）。把这笔幻想的税删掉，43.84 应原样复原。</p><p>七道题合成一条链：单子先过 15:00 的分界线定归属，T+1 数交易日告诉你何时能卖；涨跌停板给出当天报价的上下界；五笔账合出完整成本，答案唯一、逐分可核。哪一题猜错了，错的方向就指向你进场时带着的那个旧直觉——小额低估下限，大跌低估单边，大单低估费率的份量。</p><h3 id="自查-把规则放进新场景" tabindex="-1">自查：把规则放进新场景 <a class="header-anchor" href="#自查-把规则放进新场景" aria-label="Permalink to &quot;自查：把规则放进新场景&quot;">​</a></h3><ol><li>创业板某股前收盘 4.77 元。涨停价、跌停价各是多少？（提示：幅度 20%，记得处理零头。）</li><li>周二 9:21，你在开盘集合竞价里挂出一笔买单。它最早什么时候能撤？假设它当日成交，最早什么时候能卖？</li><li>朋友说：「我就买 5000 块钱的股票，费用能有多少，几毛钱吧。」用一道你已经核对过的题回应他。</li><li>周五 14:59，你卖出一笔股票并成交。这笔钱什么时候能再买股票？什么时候能转到银行卡？</li><li>反事实题：假如没有 T+1，钩子里 14:00 那张卖出委托会怎样？这条规则挡住的到底是哪种动作？</li></ol><details><summary>自查参考</summary><ol><li>4.77 × 1.2 = 5.724 → 涨停 5.72 元；4.77 × 0.8 = 3.816 → 跌停 3.82 元。同一条公式，换幅度而已（算法见「涨跌停板」一节）。</li><li>9:20–9:25 不可撤单，这张单要等 9:25 集合竞价结束才有撤单资格；当日成交则 T 是周二，最早周三卖出（三步判定见「竞价与 T+1」一节）。</li><li>把成本题 A 抄给他：5000 元的单，两笔佣金各按 5 元下限收，来回 10 元起步，还要加过户费与卖出印花税——不是几毛钱；要是来回一趟价格没动，先亏的 10 元出头全是费用。</li><li>当天（周五）就能再买其他股票；转银行卡要等下一交易日，也就是下周一。卖出资金当日可用、次日可取，「日」按交易日算。</li><li>会正常成交：当天买入当天卖出不再被拦，日内回转成为可能。T+1 挡住的正是当日回转交易——它是一条制度边界，不是技术做不到。</li></ol></details><h2 id="收束-回到那两张截图" tabindex="-1">收束：回到那两张截图 <a class="header-anchor" href="#收束-回到那两张截图" aria-label="Permalink to &quot;收束：回到那两张截图&quot;">​</a></h2><p>9:20 的买单为什么 9:25 才揭晓：它进的是集合竞价的池子，全场申报攒足 10 分钟，按最大成交量原则一次撮合出开盘价。单子的生死在 9:25 那一刻才由全场算出——之前显示「已报」是诚实状态，不是卡顿。下午的废单为什么出现：T+1 把当日买入的股票锁到下一交易日，卖出申报撞上一把还在生效的锁，只能原样弹回。两张截图都不需要修理软件，需要的是把规则装进下单前的检查：时点（15:00 分界加 T+1 数交易日）、涨跌停价（前收盘乘（1 ± 幅度）取整到分）、完整成本（五笔账合总）。</p><p>开篇的三个问题，现在各拿到一个数：单子何时成交——集合竞价 9:25 揭晓，盘中看 15:00 分界；何时可卖——T+1，按交易日数格子；代价几何——五笔账合总。六个新名词的定义与接口都收在附录「术语表」，随时回查。两个最常翻车的地方再钉一次：小额单的成本大头是 5 元佣金下限，不是费率；「次日」按交易日算，周五买入要等到下周一。佣金按课程示例值演算的口径，以及两融、大宗交易、打新这些没进本课的机制，去向都登记在附录「简化与差异清单」。</p><p>规则层到此合拢：你已经能对任意一笔委托，在下单之前算清它何时成交、何时可卖、代价几何。盘面上那些红红绿绿的蜡烛怎么读，是进场篇的下一程（第 4 章）。本章规则与费率数字均标注生效日期、以最新公告为准，全部演算不构成任何投资建议。</p>`,70)])])}const u=a(e,[["render",s]]);export{c as __pageData,u as default};
